(window.MATH_DATA = window.MATH_DATA || []).push({"id": "m2-2", "subject": "數學", "chapter": "2-2", "title": "根式的運算", "total": 71, "levels": {"必考": 8, "常考": 4}, "secs": {"基礎": "根式與最簡根式", "運算": "乘除・有理化・加減", "應用": "估算與比大小"}, "mapname": {}, "concepts": [{"id": "m2", "name": "根式的乘除", "n": 22, "level": "必考", "sec": "運算", "card": {"說明": "當 \\(a \\ge 0\\) 且 \\(b \\ge 0\\) 時，兩個二次根式相乘等於被開方數相乘後再開根號，即 \\(\\sqrt{a} \\times \\sqrt{b} = \\sqrt{a \\times b}\\)。除法運算亦同，若 \\(a \\ge 0\\) 且 \\(b &gt; 0\\)，兩根式相除等於被開方數相除後再開根號，即 \\(\\sqrt{a} \\div \\sqrt{b} = \\frac{\\sqrt{a}}{\\sqrt{b}} = \\sqrt{\\frac{a}{b}}\\)。此性質源於平方運算的分配律逆運算。", "關鍵名詞": "<b>根式乘除法則</b>（非負實數根號相乘除可直接將被開方數合併相乘除的運算規則）。", "因果／影響": "乘除法可以將分散的多個根式整合成單一根式，方便進行因數分解與化簡。", "出處": "自修第 109–110 頁／講義第 54–55 頁。", "標示": "自修標為「重點 2、重點 3」；講義標為「重點精華 1、重點精華」。"}, "imgs": [], "clusters": [{"t": "根式乘除", "n": 5, "ids": ["m2-4", "m2-5", "m2-10", "m2-22", "m2-24"]}, {"t": "乘法公式應用", "n": 3, "ids": ["m2-1", "m2-7", "mL-a8"]}, {"t": "綜合運算", "n": 2, "ids": ["m2-16", "m2-26"]}, {"t": "應用題", "n": 2, "ids": ["m2-27", "mL-a4"]}, {"t": "估算", "n": 1, "ids": ["m2-13"]}, {"t": "觀念判斷", "n": 1, "ids": ["m2-21"]}, {"t": "段考卷題目", "n": 8, "ids": ["pA6-6", "pA6-10", "pA6-12", "pA6-13", "pA10-4", "pA10-12", "pA10-13", "pA10-19"]}]}, {"id": "m6", "name": "根式大小與估算", "n": 14, "level": "必考", "sec": "應用", "card": {"說明": "對於任意兩正數 \\(a\\) 與 \\(b\\)，\\(a &gt; b \\iff \\sqrt{a} &gt; \\sqrt{b}\\)。常見比較方法為將各數平方後比較其平方值，平方值較大者原數亦較大。遇到含有負號的負平方根時，先比較其正數絕對值，加上負號後不等號方向相反；對於雙項根式（如 \\(\\sqrt{a}+\\sqrt{b}\\) 或 \\(\\sqrt{a}-\\sqrt{b}\\)），可利用平方展開或倒數有理化進行比較。", "關鍵名詞": "<b>平方比較法</b>（利用正數與其平方值單調遞增性質判定根式大小的方法）。", "因果／影響": "能快速判斷未知根式落在哪兩個連續整數之間，是估算根式數值的重要工具。", "出處": "自修第 110、125 頁／講義第 60 頁。", "標示": "講義標為「重點精華」；自修列為重要應用。"}, "imgs": [], "clusters": [{"t": "根式比大小", "n": 3, "ids": ["mL-a10", "mL-a11", "mL-a12"]}, {"t": "估算範圍", "n": 2, "ids": ["m2-14", "m2-25"]}, {"t": "估算", "n": 1, "ids": ["mL-a3"]}, {"t": "段考卷題目", "n": 8, "ids": ["pA6-2", "pA6-4", "pA6-14", "pA6-15", "pA6-16", "pA6-20", "pA10-2", "pA10-16"]}]}, {"id": "m4", "name": "有理化分母", "n": 13, "level": "必考", "sec": "運算", "card": {"說明": "利用分數的「擴分原理」，將分母中帶有根號的數轉化為整數的過程稱為有理化分母。當分母為單項（如 \\(\\frac{b}{\\sqrt{a}}\\)）時，分子分母同乘以 \\(\\sqrt{a}\\) 即可化為 \\(\\frac{b\\sqrt{a}}{a}\\)；當分母為兩項（如 \\(\\frac{c}{\\sqrt{a}+\\sqrt{b}}\\)）時，利用平方差公式 \\((x+y)(x-y)=x^2-y^2\\)，分子分母同乘以 \\((\\sqrt{a}-\\sqrt{b})\\) 使分母脫去根號。", "關鍵名詞": "<b>有理化分母</b>（藉由擴分消除分母根號，使分母變為有理整數的運算技巧）。", "因果／影響": "有理化分母不僅能達成最簡根式要求，更大幅便於數值估算與同類方根的通分加減。", "出處": "自修第 111、124 頁／講義第 55、59 頁。", "標示": "講義標為「重點精華 2、重點精華 4（必考）」；自修列為精選範例。"}, "imgs": [], "clusters": [{"t": "雙項有理化", "n": 3, "ids": ["m2-8", "m2-9", "mL-a7"]}, {"t": "有理化估算", "n": 1, "ids": ["m2-15"]}, {"t": "有理化求係數", "n": 1, "ids": ["m2-18"]}, {"t": "應用題", "n": 1, "ids": ["m2-28"]}, {"t": "有理化找規律", "n": 1, "ids": ["mL-a13"]}, {"t": "有理化綜合", "n": 1, "ids": ["mL-a14"]}, {"t": "段考卷題目", "n": 5, "ids": ["pA6-3", "pA6-8", "pA6-17", "pA6-19", "pA6-21"]}]}, {"id": "m5", "name": "同類方根與加減", "n": 12, "level": "必考", "sec": "運算", "card": {"說明": "根式做加減運算時，不能直接將根號內的數相加減（例如 \\(\\sqrt{5}+\\sqrt{3} \\ne \\sqrt{8}\\) 是常見錯誤）。必須先將各根式化為最簡根式，若化簡後「根號內的數完全相同」，才稱為同類方根。只有同類方根才能利用分配律將係數合併相加減，非同類方根則無法合併。", "關鍵名詞": "<b>同類方根</b>（化為最簡根式後，被開方數完全相同的根式）。", "因果／影響": "未化簡直接進行加減運算會導致計算全錯；化簡後合併同類項是多項四則運算的核心步驟。", "出處": "自修第 115 頁／講義第 57 頁。", "標示": "講義標為「重點精華」；觀念澄清是非題標為「易錯」。"}, "imgs": [], "clusters": [{"t": "根式加減", "n": 3, "ids": ["m2-6", "m2-20", "mL-a15"]}, {"t": "應用題", "n": 2, "ids": ["mL-a5", "mL-a6"]}, {"t": "綜合運算", "n": 1, "ids": ["m2-17"]}, {"t": "觀念判斷", "n": 1, "ids": ["mL-a1"]}, {"t": "段考卷題目", "n": 5, "ids": ["pA6-1", "pA6-5", "pA6-7", "pA6-11", "pA10-3"]}]}, {"id": "m3", "name": "最簡根式", "n": 10, "level": "必考", "sec": "基礎", "card": {"說明": "一個根式寫成 \\(r\\sqrt{n}\\)（\\(r\\) 為整數、小數或分數，\\(n\\) 為正整數）時，若滿足「被開方數 \\(n\\) 的質因數次方皆為 1」、「根號內不含分數或小數」且「分母不帶根號」，則稱為最簡根式。若被開方數質因數次方大於 1，必須將完全平方數提出根號外（如 \\(\\sqrt{a^2 b} = a\\sqrt{b}\\)）。", "關鍵名詞": "<b>最簡根式</b>（根號內為無平方因數之正整數、無分小數且分母無根號之標準化根式形式）。", "因果／影響": "根式運算的所有最終答案必須化為最簡根式，否則在段考與會考中視同未完成運算。", "出處": "自修第 111 頁／講義第 55 頁。", "標示": "自修標為「重點／老師的話（易錯提醒）」；講義標為「重點精華」。"}, "imgs": [], "clusters": [{"t": "化最簡根式", "n": 4, "ids": ["m2-2", "m2-3", "m2-19", "m2-23"]}, {"t": "觀念判斷", "n": 1, "ids": ["m2-11"]}, {"t": "最簡根式判斷", "n": 1, "ids": ["mL-a2"]}, {"t": "最簡根式應用", "n": 1, "ids": ["mL-a9"]}, {"t": "段考卷題目", "n": 3, "ids": ["pA6-9", "pA6-18", "pA6-22"]}]}, {"id": "m1", "name": "根式的表示與簡記", "n": 0, "level": "一般", "sec": "基礎", "card": {"說明": "帶有根號的數同樣具備實數性質，可以進行加、減、乘、除等四則運算，這類含有根號的算式稱為根式。在代數書寫中，文字符號與根式省略乘號的簡記規則相同，例如 \\(a \\times \\sqrt{b}\\) 可記作 \\(a\\sqrt{b}\\)。若整數或分數與根式相乘，可將非根號部分直接相乘，即 \\(a \\times b\\sqrt{n} = ab\\sqrt{n}\\)。", "關鍵名詞": "<b>根式</b>（帶有根號且能進行四則運算的代數算式）。", "因果／影響": "掌握簡記原則能避免將外乘係數與根號內的被開方數混淆，是後續根式運算與化簡的書寫基礎。", "出處": "自修第 109 頁／講義第 54 頁。", "標示": "自修標為「重點 1」；章首課程分析列為「重要性：★★★★」。"}, "imgs": [], "clusters": []}], "questions": [{"id": "m2-1", "no": "1", "c": "m2", "src": "翰林 C卷・第6回 第 1 題", "st": "考卷", "pk": "c6", "pname": "翰林 C卷・第6回（2-2）", "pord": 1, "ctx": "", "fig": "", "q": "如圖，有一梯形 $ABCD$，上底 $\\overline{AD}=\\sqrt{7}$，下底 $\\overline{BC}=5$，高 $\\overline{AH}=5-\\sqrt{7}$，則此梯形 $ABCD$ 的面積化成最簡根式為多少平方單位？（梯形面積 $=\\frac{1}{2}\\times (\\text{上底}+\\text{下底})\\times \\text{高}$）", "o": ["$7$", "$9$", "$18$", "$\\sqrt{7}+5$"], "a": 1, "e": "考點：梯形面積＋平方差公式。\n面積 $=\\dfrac{1}{2}\\times(\\sqrt{7}+5)\\times(5-\\sqrt{7})$\n$=\\dfrac{1}{2}\\times(5^2-(\\sqrt{7})^2)=\\dfrac{1}{2}\\times(25-7)=9$\n★ 看到 $(a+b)(a-b)$ 就用平方差：$a^2-b^2$，根號會消失。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "<div class=\"mfig\"><svg viewBox=\"0 0 300 170\" width=\"300\" style=\"max-width:100%;height:auto\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Times New Roman, serif\" font-size=\"15\" fill=\"#5b4a44\" stroke-linecap=\"round\"><polygon points=\"95.0,30.0 165.0,30.0 250.0,140.0 40.0,140.0\" fill=\"none\" stroke=\"#5b4a44\" stroke-width=\"1.8\"/><line x1=\"95.0\" y1=\"30.0\" x2=\"95.0\" y2=\"140.0\" stroke=\"#a8655a\" stroke-width=\"1.4\" stroke-dasharray=\"5 4\"/><polyline points=\"95.0,129.0 106.0,129.0 106.0,140.0\" fill=\"none\" stroke=\"#5b4a44\" stroke-width=\"1.3\"/><text x=\"88.0\" y=\"18.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">A</text><text x=\"172.0\" y=\"18.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">D</text><text x=\"260.0\" y=\"150.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">C</text><text x=\"30.0\" y=\"150.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">B</text><text x=\"100.0\" y=\"152.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">H</text><text x=\"130.0\" y=\"18.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">√7</text><text x=\"150.0\" y=\"158.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">5</text><text x=\"101.0\" y=\"85.0\" text-anchor=\"start\" fill=\"#a8655a\" font-size=\"14\" dominant-baseline=\"middle\">5 − √7</text></svg><div class=\"mcap\">依題意重繪</div></div>", "maps": [], "chk": "", "orig": "(B)", "fill": false, "ans": ""}, {"id": "m2-2", "no": "2", "c": "m3", "src": "翰林 C卷・第6回 第 2 題", "st": "考卷", "pk": "c6", "pname": "翰林 C卷・第6回（2-2）", "pord": 1, "ctx": "", "fig": "", "q": "將下列各根式化為最簡根式：(1) $\\sqrt{2^7 \\times 7^2}=$＿＿。", "o": [], "a": 1, "e": "考點：把完全平方因數提到根號外。\n$\\sqrt{2^7\\times7^2}=\\sqrt{2^6\\times2\\times7^2}=2^3\\times7\\times\\sqrt{2}=56\\sqrt{2}$\n★ 指數是偶數的部分整個拿出來（開根號指數減半），剩下的留在根號裡。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "$56\\sqrt{2}$", "fill": true, "ans": "$56\\sqrt{2}$"}, {"id": "m2-3", "no": "3", "c": "m3", "src": "翰林 C卷・第6回 第 3 題", "st": "考卷", "pk": "c6", "pname": "翰林 C卷・第6回（2-2）", "pord": 1, "ctx": "", "fig": "", "q": "將下列各根式化為最簡根式：(2) $\\sqrt{\\frac{5}{27}}=$＿＿。", "o": [], "a": 1, "e": "考點：根號內有分數 → 分開後有理化分母。\n$\\sqrt{\\dfrac{5}{27}}=\\dfrac{\\sqrt{5}}{\\sqrt{27}}=\\dfrac{\\sqrt{5}}{3\\sqrt{3}}=\\dfrac{\\sqrt{5}\\times\\sqrt{3}}{3\\sqrt{3}\\times\\sqrt{3}}=\\dfrac{\\sqrt{15}}{9}$\n★ 最簡根式三不準：根號內不留平方、不留分數、分母不留根號。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "$\\frac{\\sqrt{15}}{9}$", "fill": true, "ans": "$\\frac{\\sqrt{15}}{9}$"}, {"id": "m2-4", "no": "4", "c": "m2", "src": "翰林 C卷・第6回 第 4 題", "st": "考卷", "pk": "c6", "pname": "翰林 C卷・第6回（2-2）", "pord": 1, "ctx": "", "fig": "", "q": "計算下列各式並化為最簡根式：(1) $1\\frac{3}{4} \\times \\sqrt{\\frac{1}{3}} \\div \\sqrt{\\frac{7}{3}}=$＿＿。", "o": [], "a": 1, "e": "考點：帶分數先化假分數，再把根號合併。\n$1\\dfrac{3}{4}=\\dfrac{7}{4}$\n$\\sqrt{\\dfrac{1}{3}}\\div\\sqrt{\\dfrac{7}{3}}=\\sqrt{\\dfrac{1}{3}\\times\\dfrac{3}{7}}=\\sqrt{\\dfrac{1}{7}}=\\dfrac{1}{\\sqrt{7}}=\\dfrac{\\sqrt{7}}{7}$\n$\\dfrac{7}{4}\\times\\dfrac{\\sqrt{7}}{7}=\\dfrac{\\sqrt{7}}{4}$\n★ 除以根號＝乘以倒數，再合併成一個根號。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "$\\frac{\\sqrt{7}}{4}$", "fill": true, "ans": "$\\frac{\\sqrt{7}}{4}$"}, {"id": "m2-5", "no": "5", "c": "m2", "src": "翰林 C卷・第6回 第 5 題", "st": "考卷", "pk": "c6", "pname": "翰林 C卷・第6回（2-2）", "pord": 1, "ctx": "", "fig": "", "q": "計算下列各式並化為最簡根式：(2) $(5\\sqrt{10}-2\\sqrt{15}) \\div \\sqrt{5}=$＿＿。", "o": [], "a": 1, "e": "考點：分配律＋根式除法。\n$(5\\sqrt{10}-2\\sqrt{15})\\div\\sqrt{5}=5\\sqrt{\\dfrac{10}{5}}-2\\sqrt{\\dfrac{15}{5}}=5\\sqrt{2}-2\\sqrt{3}$\n★ 每一項分別除以 $\\sqrt{5}$。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "$5\\sqrt{2}-2\\sqrt{3}$", "fill": true, "ans": "$5\\sqrt{2}-2\\sqrt{3}$"}, {"id": "m2-6", "no": "6", "c": "m5", "src": "翰林 C卷・第6回 第 6 題", "st": "考卷", "pk": "c6", "pname": "翰林 C卷・第6回（2-2）", "pord": 1, "ctx": "", "fig": "", "q": "計算 $\\sqrt{180}+5\\sqrt{18}-\\sqrt{80}$ 的結果並化為最簡根式為＿＿。", "o": [], "a": 1, "e": "考點：先化最簡，再合併同類方根。\n$\\sqrt{180}=6\\sqrt{5}$，$5\\sqrt{18}=5\\times3\\sqrt{2}=15\\sqrt{2}$，$\\sqrt{80}=4\\sqrt{5}$\n原式 $=6\\sqrt{5}+15\\sqrt{2}-4\\sqrt{5}=2\\sqrt{5}+15\\sqrt{2}$\n★ 只有根號內相同的才能合併。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "$2\\sqrt{5}+15\\sqrt{2}$", "fill": true, "ans": "$2\\sqrt{5}+15\\sqrt{2}$"}, {"id": "m2-7", "no": "7", "c": "m2", "src": "翰林 C卷・第6回 第 7 題", "st": "考卷", "pk": "c6", "pname": "翰林 C卷・第6回（2-2）", "pord": 1, "ctx": "", "fig": "", "q": "如圖，傑克將 $A$、$D$ 兩個正方形與 $B$、$C$ 兩個長方形拼成一個大正方形，請利用乘法公式 $(a+b)^2=a^2+2ab+b^2$ 計算大正方形面積，並化成最簡根式為＿＿平方單位。（其中正方形 $A$ 邊長為 $5$，正方形 $D$ 邊長為 $2\\sqrt{3}$）", "o": [], "a": 1, "e": "考點：和的平方公式。\n大正方形邊長 $=5+2\\sqrt{3}$\n面積 $=(5+2\\sqrt{3})^2=5^2+2\\times5\\times2\\sqrt{3}+(2\\sqrt{3})^2=25+20\\sqrt{3}+12=37+20\\sqrt{3}$\n★ $(2\\sqrt{3})^2=4\\times3=12$，係數也要平方。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "<div class=\"mfig\"><svg viewBox=\"0 0 250 230\" width=\"250\" style=\"max-width:100%;height:auto\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Times New Roman, serif\" font-size=\"15\" fill=\"#5b4a44\" stroke-linecap=\"round\"><polygon points=\"30.0,20.0 220.0,20.0 220.0,210.0 30.0,210.0\" fill=\"none\" stroke=\"#5b4a44\" stroke-width=\"1.8\"/><line x1=\"150.0\" y1=\"20.0\" x2=\"150.0\" y2=\"210.0\" stroke=\"#5b4a44\" stroke-width=\"1.8\"/><line x1=\"30.0\" y1=\"140.0\" x2=\"220.0\" y2=\"140.0\" stroke=\"#5b4a44\" stroke-width=\"1.8\"/><text x=\"90.0\" y=\"80.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"13\" dominant-baseline=\"middle\">A（邊長 5）</text><text x=\"185.0\" y=\"80.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">B</text><text x=\"90.0\" y=\"175.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">C</text><text x=\"185.0\" y=\"175.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"14\" dominant-baseline=\"middle\">D</text><text x=\"185.0\" y=\"196.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"12\" dominant-baseline=\"middle\">2√3</text><text x=\"90.0\" y=\"8.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">5</text><text x=\"185.0\" y=\"8.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"13\" dominant-baseline=\"middle\">2√3</text></svg><div class=\"mcap\">依題意重繪</div></div>", "maps": [], "chk": "", "orig": "$37+20\\sqrt{3}$", "fill": true, "ans": "$37+20\\sqrt{3}$"}, {"id": "m2-8", "no": "8", "c": "m4", "src": "翰林 C卷・第6回 第 8 題", "st": "考卷", "pk": "c6", "pname": "翰林 C卷・第6回（2-2）", "pord": 1, "ctx": "", "fig": "", "q": "利用乘法公式化簡 $\\frac{\\sqrt{5}-\\sqrt{3}}{\\sqrt{5}+\\sqrt{3}}$ 得最簡根式為＿＿。", "o": [], "a": 1, "e": "考點：分母是兩項 → 同乘共軛式。\n$\\dfrac{\\sqrt{5}-\\sqrt{3}}{\\sqrt{5}+\\sqrt{3}}=\\dfrac{(\\sqrt{5}-\\sqrt{3})^2}{(\\sqrt{5}+\\sqrt{3})(\\sqrt{5}-\\sqrt{3})}=\\dfrac{5-2\\sqrt{15}+3}{5-3}=\\dfrac{8-2\\sqrt{15}}{2}=4-\\sqrt{15}$\n★ 共軛式：$\\sqrt{a}+\\sqrt{b}$ 配 $\\sqrt{a}-\\sqrt{b}$。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "$4-\\sqrt{15}$", "fill": true, "ans": "$4-\\sqrt{15}$"}, {"id": "m2-9", "no": "9", "c": "m4", "src": "翰林 C卷・第6回 第 9 題", "st": "考卷", "pk": "c6", "pname": "翰林 C卷・第6回（2-2）", "pord": 1, "ctx": "", "fig": "", "q": "利用 $(a+b)(a-b)=a^2-b^2$ 化簡 $\\frac{4\\sqrt{21}}{\\sqrt{7}-\\sqrt{3}}$。", "o": [], "a": 1, "e": "考點：雙項有理化。\n$\\dfrac{4\\sqrt{21}}{\\sqrt{7}-\\sqrt{3}}=\\dfrac{4\\sqrt{21}(\\sqrt{7}+\\sqrt{3})}{7-3}=\\sqrt{21}(\\sqrt{7}+\\sqrt{3})=\\sqrt{147}+\\sqrt{63}=7\\sqrt{3}+3\\sqrt{7}$\n★ 分母 $7-3=4$ 剛好和分子的 4 約掉。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "$7\\sqrt{3}+3\\sqrt{7}$", "fill": true, "ans": "$7\\sqrt{3}+3\\sqrt{7}$"}, {"id": "m2-10", "no": "10", "c": "m2", "src": "翰林 C卷・第6回 第 10 題", "st": "考卷", "pk": "c6", "pname": "翰林 C卷・第6回（2-2）", "pord": 1, "ctx": "", "fig": "", "q": "若一個長方體的體積為 $\\sqrt{35}$ 立方公分，其長為 $\\sqrt{\\frac{8}{3}}$ 公分，寬為 $\\sqrt{\\frac{21}{32}}$ 公分，求此長方體的高為多少公分？（以最簡根式表示）", "o": [], "a": 1, "e": "考點：長方體體積＝長×寬×高。\n長×寬 $=\\sqrt{\\dfrac{8}{3}\\times\\dfrac{21}{32}}=\\sqrt{\\dfrac{7}{4}}=\\dfrac{\\sqrt{7}}{2}$\n高 $=\\sqrt{35}\\div\\dfrac{\\sqrt{7}}{2}=\\dfrac{2\\sqrt{35}}{\\sqrt{7}}=2\\sqrt{5}$（公分）\n★ 先約分再開根號，數字會小很多。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "$2\\sqrt{5}$", "fill": true, "ans": "$2\\sqrt{5}$ 公分"}, {"id": "m2-11", "no": "11", "c": "m3", "src": "翰林 B卷・第10回 第 1 題", "st": "考卷", "pk": "b10", "pname": "翰林 B卷・第10回（2-2～3-2 複習）", "pord": 2, "ctx": "", "fig": "", "q": "下列算式及敘述何者正確？", "o": ["$\\frac{\\sqrt{2}}{5}$ 是最簡根式", "$\\sqrt{2}\\times \\sqrt{5}=2\\sqrt{5}$", "$\\sqrt{2}+\\sqrt{5}=\\sqrt{7}$", "$6\\sqrt{3}-4\\sqrt{3}=2$"], "a": 0, "e": "考點：最簡根式與運算觀念。\n(A) $\\dfrac{\\sqrt{2}}{5}$：根號內無平方因數、分母沒有根號 → 是最簡根式 ✔\n(B) $\\sqrt{2}\\times\\sqrt{5}=\\sqrt{10}$，不是 $2\\sqrt{5}$。\n(C) $\\sqrt{2}+\\sqrt{5}$ 不能合併，$\\ne\\sqrt{7}$。\n(D) $6\\sqrt{3}-4\\sqrt{3}=2\\sqrt{3}$，不是 2。\n★ 根號相加不能把裡面的數加起來。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "(A)", "fill": false, "ans": ""}, {"id": "m2-13", "no": "13", "c": "m2", "src": "翰林 B卷・第10回 第 2 題", "st": "考卷", "pk": "b10", "pname": "翰林 B卷・第10回（2-2～3-2 複習）", "pord": 2, "ctx": "", "fig": "", "q": "已知 $\\sqrt{5}\\fallingdotseq 2.236$，$\\sqrt{50}\\fallingdotseq 7.071$，則 $\\sqrt{5000}$ 的近似值為下列何者？", "o": ["$22.36$", "$70.71$", "$223.6$", "$707.1$"], "a": 1, "e": "考點：利用 $\\sqrt{100}=10$ 調整位數。\n$\\sqrt{5000}=\\sqrt{50\\times100}=10\\sqrt{50}\\fallingdotseq10\\times7.071=70.71$\n★ 根號內每移動兩位小數點，答案移動一位。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "(B)", "fill": false, "ans": ""}, {"id": "m2-14", "no": "14", "c": "m6", "src": "翰林 B卷・第10回 第 3 題", "st": "考卷", "pk": "b10", "pname": "翰林 B卷・第10回（2-2～3-2 複習）", "pord": 2, "ctx": "", "fig": "", "q": "試判斷 $\\frac{2}{\\sqrt{13}-1}$ 之值介於下列哪兩個整數之間？", "o": ["$3$、$4$", "$4$、$5$", "$5$、$6$", "$0$、$1$"], "a": 3, "e": "考點：有理化後估算。\n$\\dfrac{2}{\\sqrt{13}-1}=\\dfrac{2(\\sqrt{13}+1)}{13-1}=\\dfrac{\\sqrt{13}+1}{6}$\n$3<\\sqrt{13}<4$ → $4<\\sqrt{13}+1<5$ → $\\dfrac{4}{6}<\\dfrac{\\sqrt{13}+1}{6}<\\dfrac{5}{6}$\n所以介於 0 和 1 之間。\n★ 分母有根號時，先有理化再估算。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "(D)", "fill": false, "ans": ""}, {"id": "m2-15", "no": "15", "c": "m4", "src": "翰林 B卷・第10回 第 4 題", "st": "考卷", "pk": "b10", "pname": "翰林 B卷・第10回（2-2～3-2 複習）", "pord": 2, "ctx": "", "fig": "", "q": "設 $\\frac{\\sqrt{11}+\\sqrt{10}}{\\sqrt{11}-\\sqrt{10}}$ 的整數部分為 $k$，則 $k=$？", "o": ["$13$", "$41$", "$42$", "$43$"], "a": 1, "e": "考點：雙項有理化後估算整數部分。\n$\\dfrac{\\sqrt{11}+\\sqrt{10}}{\\sqrt{11}-\\sqrt{10}}=\\dfrac{(\\sqrt{11}+\\sqrt{10})^2}{11-10}=21+2\\sqrt{110}$\n$10^2=100<110<121=11^2$，且 $10.5^2=110.25$ → $\\sqrt{110}\\fallingdotseq10.49$\n$2\\sqrt{110}\\fallingdotseq20.98$ → $21+20.98=41.98$ → 整數部分 $k=41$\n★ 估算要夠精確，$2\\sqrt{110}$ 還沒到 21。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "(B)", "fill": false, "ans": ""}, {"id": "m2-16", "no": "16", "c": "m2", "src": "翰林 B卷・第10回 第 5 題", "st": "考卷", "pk": "b10", "pname": "翰林 B卷・第10回（2-2～3-2 複習）", "pord": 2, "ctx": "", "fig": "", "q": "計算下列各式，並將結果化為最簡根式：(1) $\\frac{\\sqrt{7}}{\\sqrt{3}}\\times \\frac{\\sqrt{42}}{5}-\\frac{\\sqrt{6}}{\\sqrt{2}}=$＿＿。", "o": [], "a": 1, "e": "考點：根式乘除、化簡（教用答案有誤，以下為驗算結果）。\n$\\dfrac{\\sqrt{7}}{\\sqrt{3}}\\times\\dfrac{\\sqrt{42}}{5}=\\dfrac{\\sqrt{7\\times42\\div3}}{5}=\\dfrac{\\sqrt{98}}{5}=\\dfrac{7\\sqrt{2}}{5}$\n$\\dfrac{\\sqrt{6}}{\\sqrt{2}}=\\sqrt{3}=\\dfrac{5\\sqrt{3}}{5}$\n原式 $=\\dfrac{7\\sqrt{2}-5\\sqrt{3}}{5}$\n★ 通分時 $\\sqrt{3}$ 要寫成 $\\dfrac{5\\sqrt{3}}{5}$。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "$\\frac{7\\sqrt{2}-15}{5}$", "fill": true, "ans": "$\\frac{7\\sqrt{2}-5\\sqrt{3}}{5}$"}, {"id": "m2-17", "no": "17", "c": "m5", "src": "翰林 B卷・第10回 第 6 題", "st": "考卷", "pk": "b10", "pname": "翰林 B卷・第10回（2-2～3-2 複習）", "pord": 2, "ctx": "", "fig": "", "q": "計算下列各式，並將結果化為最簡根式：(2) $\\sqrt{18}-\\frac{\\sqrt{7}}{\\sqrt{3}+2}+\\sqrt{32}=$＿＿。", "o": [], "a": 1, "e": "考點：化簡＋有理化＋合併（教用答案正負號有誤，以下為驗算結果）。\n$\\sqrt{18}=3\\sqrt{2}$，$\\sqrt{32}=4\\sqrt{2}$\n$\\dfrac{\\sqrt{7}}{\\sqrt{3}+2}=\\dfrac{\\sqrt{7}(2-\\sqrt{3})}{(2+\\sqrt{3})(2-\\sqrt{3})}=\\dfrac{2\\sqrt{7}-\\sqrt{21}}{4-3}=2\\sqrt{7}-\\sqrt{21}$\n原式 $=3\\sqrt{2}-(2\\sqrt{7}-\\sqrt{21})+4\\sqrt{2}=7\\sqrt{2}-2\\sqrt{7}+\\sqrt{21}$\n★ 前面是減號，括號打開要變號。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "$7\\sqrt{2}+2\\sqrt{7}-\\sqrt{21}$", "fill": true, "ans": "$7\\sqrt{2}-2\\sqrt{7}+\\sqrt{21}$"}, {"id": "m2-18", "no": "18", "c": "m4", "src": "自修 第118頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "將 $\\frac{9}{4-\\sqrt{7}}$ 化簡為 $a+b\\sqrt{7}$，其中 $a$、$b$ 為整數，求 $a+b$ 之值為何？", "o": ["$5$", "$3$", "$-9$", "$-15$"], "a": 0, "e": "考點：雙項有理化。\n$\\dfrac{9}{4-\\sqrt{7}}=\\dfrac{9(4+\\sqrt{7})}{16-7}=\\dfrac{9(4+\\sqrt{7})}{9}=4+\\sqrt{7}$\n$a=4$，$b=1$ → $a+b=5$", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "(A)", "fill": false, "ans": ""}, {"id": "m2-19", "no": "19", "c": "m3", "src": "自修 第118頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "化簡 $\\sqrt{135}$ 的結果為下列何者？", "o": ["$3\\sqrt{5}$", "$27\\sqrt{5}$", "$3\\sqrt{15}$", "$9\\sqrt{15}$"], "a": 2, "e": "考點：質因數分解後提出平方數。\n$135=3^3\\times5=3^2\\times15$ → $\\sqrt{135}=3\\sqrt{15}$", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "(C)", "fill": false, "ans": ""}, {"id": "m2-20", "no": "20", "c": "m5", "src": "自修 第118頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "算式 $\\sqrt{50}+\\sqrt{48}-\\sqrt{18}-\\sqrt{12}$ 之值為何？", "o": ["$2\\sqrt{17}$", "$4\\sqrt{17}$", "$2\\sqrt{2}+2\\sqrt{3}$", "$16\\sqrt{2}+12\\sqrt{3}$"], "a": 2, "e": "考點：先化最簡再合併。\n$\\sqrt{50}=5\\sqrt{2}$、$\\sqrt{48}=4\\sqrt{3}$、$\\sqrt{18}=3\\sqrt{2}$、$\\sqrt{12}=2\\sqrt{3}$\n原式 $=(5-3)\\sqrt{2}+(4-2)\\sqrt{3}=2\\sqrt{2}+2\\sqrt{3}$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "(C)", "fill": false, "ans": ""}, {"id": "m2-21", "no": "21", "c": "m2", "src": "自修 第118頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "下列等式何者不成立？", "o": ["$4\\sqrt{3}+2\\sqrt{3}=6\\sqrt{3}$", "$4\\sqrt{3}-2\\sqrt{3}=2\\sqrt{3}$", "$4\\sqrt{3}\\times 2\\sqrt{3}=8\\sqrt{3}$", "$4\\sqrt{3}\\div 2\\sqrt{3}=2$"], "a": 2, "e": "考點：根式四則運算。\n(C) $4\\sqrt{3}\\times2\\sqrt{3}=8\\times(\\sqrt{3})^2=8\\times3=24$，不是 $8\\sqrt{3}$ → 不成立。\n(A)(B) 同類方根合併係數 ✔；(D) $\\dfrac{4\\sqrt{3}}{2\\sqrt{3}}=2$ ✔\n★ $\\sqrt{3}\\times\\sqrt{3}=3$。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "(C)", "fill": false, "ans": ""}, {"id": "m2-22", "no": "22", "c": "m2", "src": "自修 第118頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "算式 $\\sqrt{2}\\times (\\sqrt{48}-\\sqrt{12})$ 之值為何？", "o": ["$6\\sqrt{2}$", "$2\\sqrt{6}$", "$2\\sqrt{21}$", "$4\\sqrt{6}-2\\sqrt{3}$"], "a": 1, "e": "考點：先化簡括號內再乘。\n$\\sqrt{48}-\\sqrt{12}=4\\sqrt{3}-2\\sqrt{3}=2\\sqrt{3}$\n$\\sqrt{2}\\times2\\sqrt{3}=2\\sqrt{6}$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "(B)", "fill": false, "ans": ""}, {"id": "m2-23", "no": "23", "c": "m3", "src": "自修 第118頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "若 $\\sqrt{44}=2\\sqrt{a}$，$\\sqrt{54}=3\\sqrt{b}$，則 $a+b$ 之值為何？", "o": ["$13$", "$17$", "$24$", "$40$"], "a": 1, "e": "考點：化最簡根式。\n$\\sqrt{44}=\\sqrt{4\\times11}=2\\sqrt{11}$ → $a=11$\n$\\sqrt{54}=\\sqrt{9\\times6}=3\\sqrt{6}$ → $b=6$\n$a+b=17$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "(B)", "fill": false, "ans": ""}, {"id": "m2-24", "no": "24", "c": "m2", "src": "自修 第118頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "算式 $\\sqrt{6}\\times (\\frac{1}{\\sqrt{3}}-1)$ 之值為何？", "o": ["$\\sqrt{2}-\\sqrt{6}$", "$\\sqrt{2}-1$", "$2-\\sqrt{6}$", "$1$"], "a": 0, "e": "考點：分配律。\n$\\sqrt{6}\\times\\dfrac{1}{\\sqrt{3}}-\\sqrt{6}=\\sqrt{2}-\\sqrt{6}$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "(A)", "fill": false, "ans": ""}, {"id": "m2-25", "no": "25", "c": "m6", "src": "自修 第119頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "若一正方形的面積為 $20$ 平方公分，周長為 $x$ 公分，則 $x$ 的值介於下列哪兩個整數之間？", "o": ["$16$、$17$", "$17$、$18$", "$18$、$19$", "$19$、$20$"], "a": 1, "e": "考點：估算根式。\n邊長 $=\\sqrt{20}=2\\sqrt{5}$，周長 $x=4\\times2\\sqrt{5}=8\\sqrt{5}=\\sqrt{320}$\n$17^2=289<320<324=18^2$ → $17<x<18$\n★ 把係數放回根號內再比較：$8\\sqrt{5}=\\sqrt{64\\times5}$。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "(B)", "fill": false, "ans": ""}, {"id": "m2-26", "no": "26", "c": "m2", "src": "自修 第119頁", "st": "自修", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "算式 $(\\sqrt{6}+\\sqrt{10}\\times \\sqrt{15})\\times \\sqrt{3}$ 之值為何？", "o": ["$2\\sqrt{42}$", "$12\\sqrt{5}$", "$12\\sqrt{13}$", "$18\\sqrt{2}$"], "a": 3, "e": "考點：先乘除後加減。\n$\\sqrt{10}\\times\\sqrt{15}=\\sqrt{150}=5\\sqrt{6}$\n括號內 $=\\sqrt{6}+5\\sqrt{6}=6\\sqrt{6}$\n$6\\sqrt{6}\\times\\sqrt{3}=6\\sqrt{18}=6\\times3\\sqrt{2}=18\\sqrt{2}$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "(D)", "fill": false, "ans": ""}, {"id": "m2-27", "no": "27", "c": "m2", "src": "講義 第66頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "有一個長方體的體積為 $(12-2\\sqrt{3})$ 立方公分，且長為 $\\sqrt{3}$ 公分，寬為 $\\sqrt{2}$ 公分，則：(1) 高為多少公分？（化為最簡根式）(2) 邊長總和為多少公分？（化為最簡根式）", "o": [], "a": 1, "e": "考點：長方體體積與邊長總和（教用答案第 (2) 題有誤，以下為驗算結果）。\n(1) 高 $=\\dfrac{12-2\\sqrt{3}}{\\sqrt{3}\\times\\sqrt{2}}=\\dfrac{12-2\\sqrt{3}}{\\sqrt{6}}=\\dfrac{(12-2\\sqrt{3})\\sqrt{6}}{6}=2\\sqrt{6}-\\sqrt{2}$（公分）\n(2) 長方體有 12 條邊，長、寬、高各 4 條：\n$4\\times(\\sqrt{3}+\\sqrt{2}+2\\sqrt{6}-\\sqrt{2})=4\\times(\\sqrt{3}+2\\sqrt{6})=4\\sqrt{3}+8\\sqrt{6}$（公分）\n★ 長方體邊長總和＝4×（長＋寬＋高），$\\sqrt{2}$ 會互相抵消。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "(1) $2\\sqrt{6}-\\sqrt{2}$ 公分；(2) $4\\sqrt{3}+4\\sqrt{2}+8\\sqrt{6}$ 公分", "fill": true, "ans": "(1) $2\\sqrt{6}-\\sqrt{2}$ 公分　(2) $4\\sqrt{3}+8\\sqrt{6}$ 公分"}, {"id": "m2-28", "no": "28", "c": "m4", "src": "講義 第66頁", "st": "講義", "pk": null, "pname": null, "pord": 0, "ctx": "", "fig": "", "q": "如圖，已知市面上 A4 紙張的長：寬之比值為 $\\sqrt{2}$（$\\overline{AB}>\\overline{AD}$），若將 $\\overline{AD}$ 沿 $\\overline{AF}$ 對摺使之與 $\\overline{AB}$ 疊合，$D$ 點會落在 $\\overline{AB}$ 上的 $E$ 點，且 $\\overline{AD}$ 的長度為 $a$，則：(1) $\\overline{EB}$ 的長度為何？（以 $a$ 表示）(2) 矩形 $EBCF$ 的長（$\\overline{EF}$）：寬（$\\overline{EB}$）之比值為何？", "o": [], "a": 1, "e": "考點：A4 紙的長寬比與有理化。\n$\\overline{AD}=a$，$\\overline{AB}=\\sqrt{2}a$；摺過去 $\\overline{AE}=\\overline{AD}=a$\n(1) $\\overline{EB}=\\sqrt{2}a-a=(\\sqrt{2}-1)a$\n(2) $\\overline{EF}=\\overline{AD}=a$，比值 $=\\dfrac{a}{(\\sqrt{2}-1)a}=\\dfrac{\\sqrt{2}+1}{(\\sqrt{2}-1)(\\sqrt{2}+1)}=\\sqrt{2}+1$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "<div class=\"mfig\"><svg viewBox=\"0 0 253 190\" width=\"253\" style=\"max-width:100%;height:auto\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"Times New Roman, serif\" font-size=\"15\" fill=\"#5b4a44\" stroke-linecap=\"round\"><polygon points=\"30.0,30.0 213.8,30.0 213.8,160.0 30.0,160.0\" fill=\"none\" stroke=\"#5b4a44\" stroke-width=\"1.8\"/><line x1=\"160.0\" y1=\"30.0\" x2=\"160.0\" y2=\"160.0\" stroke=\"#5b4a44\" stroke-width=\"1.8\"/><line x1=\"30.0\" y1=\"30.0\" x2=\"160.0\" y2=\"160.0\" stroke=\"#a8655a\" stroke-width=\"1.6\" stroke-dasharray=\"5 4\"/><text x=\"22.0\" y=\"20.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">A</text><text x=\"160.0\" y=\"18.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">E</text><text x=\"221.8\" y=\"20.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">B</text><text x=\"221.8\" y=\"170.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">C</text><text x=\"160.0\" y=\"172.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">F</text><text x=\"22.0\" y=\"170.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">D</text><text x=\"18.0\" y=\"95.0\" text-anchor=\"middle\" fill=\"#5b4a44\" font-size=\"15\" dominant-baseline=\"middle\">a</text><text x=\"80.0\" y=\"120.0\" text-anchor=\"middle\" fill=\"#a8655a\" font-size=\"12\" dominant-baseline=\"middle\">摺痕</text></svg><div class=\"mcap\">依題意重繪</div></div>", "maps": [], "chk": "", "orig": "(1) $(\\sqrt{2}-1)a$；(2) $\\sqrt{2}+1$", "fill": true, "ans": "(1) $(\\sqrt{2}-1)a$　(2) $\\sqrt{2}+1$"}, {"id": "mL-a1", "no": "a1", "c": "m5", "src": "良師 第63頁・會考模擬 1", "st": "良師", "pk": "ls", "pname": "良師講義（精選）", "pord": 999, "ctx": "", "fig": "", "q": "下列哪一個等式錯誤？", "o": ["$\\sqrt{6}\\times\\sqrt{3}=\\sqrt{18}$", "$\\sqrt{6}\\div\\sqrt{3}=\\sqrt{2}$", "$\\sqrt{6}+\\sqrt{3}=\\sqrt{9}$", "$(\\sqrt{6}\\times\\sqrt{3})^2=18$"], "a": 2, "e": "考點：根號「乘除可以合併，加減不行」。\n(A) 乘法：$\\sqrt{6}\\times\\sqrt{3}=\\sqrt{6\\times3}=\\sqrt{18}$ ✔\n(B) 除法：$\\sqrt{6}\\div\\sqrt{3}=\\sqrt{6\\div3}=\\sqrt{2}$ ✔\n(C) 加法不能把根號裡的數加起來：$\\sqrt{6}+\\sqrt{3}\\fallingdotseq2.45+1.73=4.18$，但 $\\sqrt{9}=3$ → 錯誤 ✘\n(D) $(\\sqrt{18})^2=18$ ✔\n★ 口訣：根號乘除能合體，加減只能看同類。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "mL-a2", "no": "a2", "c": "m3", "src": "良師 第63頁・會考模擬 2", "st": "良師", "pk": "ls", "pname": "良師講義（精選）", "pord": 999, "ctx": "", "fig": "", "q": "下列何者為最簡根式？", "o": ["$\\sqrt{62}$", "$\\sqrt{52}$", "$\\sqrt{\\frac{1}{3}}$", "$\\sqrt{0.11}$"], "a": 0, "e": "考點：最簡根式三不準——根號內不留平方因數、不留分數小數、分母不留根號。\n(A) $62=2\\times31$，沒有平方因數 → 最簡 ✔\n(B) $52=4\\times13$，可以化成 $2\\sqrt{13}$ → 不是最簡\n(C) 根號內有分數 → 不是最簡（應寫成 $\\dfrac{\\sqrt{3}}{3}$）\n(D) 根號內有小數 → 不是最簡\n★ 判斷方法：先質因數分解，看有沒有「同一個質數出現兩次」。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "mL-a3", "no": "a3", "c": "m6", "src": "良師 第63頁・會考模擬 4", "st": "良師", "pk": "ls", "pname": "良師講義（精選）", "pord": 999, "ctx": "", "fig": "", "q": "已知 $\\sqrt{29}\\fallingdotseq5.385$、$\\sqrt{290}\\fallingdotseq17.029$，則 $\\sqrt{2.9}+\\sqrt{2900}$ 的整數部分為何？", "o": ["$22$", "$44$", "$54$", "$55$"], "a": 3, "e": "考點：根號內小數點每移動「兩位」，答案移動「一位」。\n$\\sqrt{2.9}=\\sqrt{\\dfrac{290}{100}}=\\dfrac{\\sqrt{290}}{10}\\fallingdotseq1.7029$\n$\\sqrt{2900}=\\sqrt{29\\times100}=10\\sqrt{29}\\fallingdotseq53.85$\n相加 $\\fallingdotseq55.55$ → 整數部分是 $55$\n★ 先看根號內是 29 還是 290「搬」出來的，不要選錯。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "mL-a4", "no": "a4", "c": "m2", "src": "良師 第63頁・會考模擬 5", "st": "良師", "pk": "ls", "pname": "良師講義（精選）", "pord": 999, "ctx": "", "fig": "", "q": "若一三角形的高為 $\\sqrt{6}$，面積為 $\\sqrt{18}$ 平方單位，則此高對應的底為何？", "o": ["$\\sqrt{3}$", "$\\sqrt{6}$", "$2\\sqrt{3}$", "$2\\sqrt{6}$"], "a": 2, "e": "考點：三角形面積 $=\\dfrac{1}{2}\\times$ 底 $\\times$ 高。\n$\\sqrt{18}=\\dfrac{1}{2}\\times$ 底 $\\times\\sqrt{6}$\n底 $=\\dfrac{2\\sqrt{18}}{\\sqrt{6}}=2\\sqrt{\\dfrac{18}{6}}=2\\sqrt{3}$\n★ 別忘了三角形面積的 $\\dfrac{1}{2}$，所以要乘 2。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "mL-a5", "no": "a5", "c": "m5", "src": "良師 第63頁・會考模擬 6", "st": "良師", "pk": "ls", "pname": "良師講義（精選）", "pord": 999, "ctx": "", "fig": "", "q": "有一周長為 $12\\sqrt{3}$ 的長方形，若其中一邊長為 $\\sqrt{75}$，則另一邊長為何？", "o": ["$7\\sqrt{3}$", "$4\\sqrt{3}$", "$3$", "$\\sqrt{3}$"], "a": 3, "e": "考點：周長÷2＝長＋寬；先化最簡才能相減。\n長＋寬 $=12\\sqrt{3}\\div2=6\\sqrt{3}$\n$\\sqrt{75}=\\sqrt{25\\times3}=5\\sqrt{3}$\n另一邊 $=6\\sqrt{3}-5\\sqrt{3}=\\sqrt{3}$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "mL-a6", "no": "a6", "c": "m5", "src": "良師 第63頁・會考模擬 7", "st": "良師", "pk": "ls", "pname": "良師講義（精選）", "pord": 999, "ctx": "", "fig": "", "q": "將三個面積分別為 2、8、18 平方公分的正方形摺紙並排在一起（底邊對齊），$\\overline{AB}$、$\\overline{CE}$、$\\overline{GJ}$ 分別是三個正方形的一邊，則 $\\overline{AB}+\\overline{CE}+\\overline{GJ}$ 的長度為多少公分？", "o": ["$3\\sqrt{2}$", "$6\\sqrt{2}$", "$\\sqrt{2+8+18}$", "$\\sqrt{2\\times8\\times18}$"], "a": 1, "e": "考點：正方形邊長 $=\\sqrt{\\text{面積}}$，化最簡後同類方根相加。\n$\\sqrt{2}$、$\\sqrt{8}=2\\sqrt{2}$、$\\sqrt{18}=3\\sqrt{2}$\n相加 $=(1+2+3)\\sqrt{2}=6\\sqrt{2}$\n(C) 是常見錯誤：根號不能先把裡面加起來。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "mL-a7", "no": "a7", "c": "m4", "src": "良師 第64頁・會考模擬 12", "st": "良師", "pk": "ls", "pname": "良師講義（精選）", "pord": 999, "ctx": "", "fig": "", "q": "計算 $\\dfrac{\\sqrt{5}+\\sqrt{3}}{\\sqrt{5}-\\sqrt{3}}-\\dfrac{\\sqrt{5}-\\sqrt{3}}{\\sqrt{5}+\\sqrt{3}}=$？", "o": ["$8$", "$2\\sqrt{15}$", "$-2\\sqrt{15}$", "$-8$"], "a": 1, "e": "考點：雙項有理化——分子分母同乘「共軛式」。\n第一項：$\\dfrac{(\\sqrt{5}+\\sqrt{3})^2}{(\\sqrt{5})^2-(\\sqrt{3})^2}=\\dfrac{5+2\\sqrt{15}+3}{2}=4+\\sqrt{15}$\n第二項：$\\dfrac{(\\sqrt{5}-\\sqrt{3})^2}{5-3}=\\dfrac{8-2\\sqrt{15}}{2}=4-\\sqrt{15}$\n相減：$(4+\\sqrt{15})-(4-\\sqrt{15})=2\\sqrt{15}$\n★ 共軛式：$\\sqrt{a}+\\sqrt{b}$ 配 $\\sqrt{a}-\\sqrt{b}$，相乘 $=a-b$，根號就不見了。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "mL-a8", "no": "a8", "c": "m2", "src": "良師 第64頁・會考模擬 13", "st": "良師", "pk": "ls", "pname": "良師講義（精選）", "pord": 999, "ctx": "", "fig": "", "q": "計算 $(\\sqrt{6}+2\\sqrt{3})^2$，並將結果化為最簡根式 $a+b\\sqrt{c}$，則 $a+b+c=$？", "o": ["$18$", "$24$", "$32$", "$38$"], "a": 2, "e": "考點：和的平方公式 $(x+y)^2=x^2+2xy+y^2$。\n$(\\sqrt{6})^2=6$\n$2\\times\\sqrt{6}\\times2\\sqrt{3}=4\\sqrt{18}=4\\times3\\sqrt{2}=12\\sqrt{2}$\n$(2\\sqrt{3})^2=4\\times3=12$\n合計 $=18+12\\sqrt{2}$ → $a=18$，$b=12$，$c=2$，$a+b+c=32$\n★ 中間項 $\\sqrt{18}$ 一定要化成 $3\\sqrt{2}$，才算最簡。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "mL-a9", "no": "a9", "c": "m3", "src": "良師 第64頁・會考模擬 14", "st": "良師", "pk": "ls", "pname": "良師講義（精選）", "pord": 999, "ctx": "", "fig": "", "q": "已知 $a$、$b$ 皆為正整數，且 $\\sqrt{240a}$、$\\sqrt{\\dfrac{240}{b}}$ 的值皆為正整數，則 $a+b$ 的最小值為何？", "o": ["$15$", "$30$", "$45$", "$60$"], "a": 1, "e": "考點：根號內要是「完全平方數」才能開成整數。\n質因數分解：$240=2^4\\times3\\times5$，指數是奇數的有 3 和 5。\n$\\sqrt{240a}$：要補一個 3 和一個 5 → $a$ 最小 $=15$（$240\\times15=3600=60^2$）\n$\\sqrt{\\dfrac{240}{b}}$：要把 3 和 5 除掉 → $b$ 最小 $=15$（$240\\div15=16=4^2$）\n$a+b=30$\n★ 開成整數＝每個質因數的次方都是偶數。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "mL-a10", "no": "a10", "c": "m6", "src": "良師 第64頁・會考模擬 15", "st": "良師", "pk": "ls", "pname": "良師講義（精選）", "pord": 999, "ctx": "", "fig": "", "q": "比較 $\\sqrt{6}+\\sqrt{5}$ 和 $3+\\sqrt{2}$ 兩數的大小關係，下列何者正確？", "o": ["$\\sqrt{6}+\\sqrt{5}>3+\\sqrt{2}$", "$\\sqrt{6}+\\sqrt{5}=3+\\sqrt{2}$", "$\\sqrt{6}+\\sqrt{5}<3+\\sqrt{2}$", "無法比較"], "a": 0, "e": "考點：兩個正數比大小，可以比「平方」。\n$(\\sqrt{6}+\\sqrt{5})^2=6+5+2\\sqrt{30}=11+2\\sqrt{30}$\n$(3+\\sqrt{2})^2=9+2+6\\sqrt{2}=11+2\\sqrt{18}$\n$\\sqrt{30}>\\sqrt{18}$ → $\\sqrt{6}+\\sqrt{5}$ 比較大\n★ 平方後常數一樣（都是 11），只要比根號部分。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "mL-a11", "no": "a11", "c": "m6", "src": "良師 第64頁・會考模擬 16", "st": "良師", "pk": "ls", "pname": "良師講義（精選）", "pord": 999, "ctx": "", "fig": "", "q": "若 $a=2\\sqrt{3}+\\sqrt{5}$、$b=3\\sqrt{2}+\\sqrt{5}$、$c=4+\\sqrt{5}$，則 $a$、$b$、$c$ 的大小關係為何？", "o": ["$a>b>c$", "$b>c>a$", "$c>b>a$", "無法比較"], "a": 1, "e": "考點：都有 $\\sqrt{5}$，只要比前面那一項；把係數放回根號內比較。\n$2\\sqrt{3}=\\sqrt{12}$、$3\\sqrt{2}=\\sqrt{18}$、$4=\\sqrt{16}$\n$\\sqrt{18}>\\sqrt{16}>\\sqrt{12}$ → $b>c>a$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "mL-a12", "no": "a12", "c": "m6", "src": "良師 第104頁・段考試題 3", "st": "良師", "pk": "ls", "pname": "良師講義（精選）", "pord": 999, "ctx": "", "fig": "", "q": "若 $A=\\sqrt{15}+\\sqrt{5}$，$B=\\sqrt{18}+\\sqrt{2}$，$C=6$，試比較 $A$、$B$、$C$ 三數的大小關係為何？", "o": ["$C>B>A$", "$A>C>B$", "$A>B>C$", "$B>A>C$"], "a": 1, "e": "考點：先化簡，再平方比較。\n$B=3\\sqrt{2}+\\sqrt{2}=4\\sqrt{2}=\\sqrt{32}$\n$A^2=15+5+2\\sqrt{75}=20+10\\sqrt{3}\\fallingdotseq20+17.3=37.3$\n$C^2=36$，$B^2=32$\n$37.3>36>32$ → $A>C>B$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "mL-a13", "no": "a13", "c": "m4", "src": "良師 第105頁・段考試題 13", "st": "良師", "pk": "ls", "pname": "良師講義（精選）", "pord": 999, "ctx": "", "fig": "", "q": "已知 $a$、$b$ 為正整數，$a\\ne b$，且 $\\dfrac{1}{\\sqrt{a}+\\sqrt{b}}=\\dfrac{\\sqrt{a}-\\sqrt{b}}{a-b}$。計算 $\\dfrac{1}{\\sqrt{1}+\\sqrt{2}}+\\dfrac{1}{\\sqrt{2}+\\sqrt{3}}+\\cdots+\\dfrac{1}{\\sqrt{48}+\\sqrt{49}}=$？", "o": ["$4$", "$5$", "$6$", "$7$"], "a": 2, "e": "考點：有理化後「前後抵消」。\n每一項有理化：$\\dfrac{1}{\\sqrt{n}+\\sqrt{n+1}}=\\dfrac{\\sqrt{n}-\\sqrt{n+1}}{n-(n+1)}=\\sqrt{n+1}-\\sqrt{n}$\n原式 $=(\\sqrt{2}-\\sqrt{1})+(\\sqrt{3}-\\sqrt{2})+\\cdots+(\\sqrt{49}-\\sqrt{48})$\n中間全部抵消，剩下 $\\sqrt{49}-\\sqrt{1}=7-1=6$\n★ 這種題目寫出前兩項和最後一項，就能看出規律。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "mL-a14", "no": "a14", "c": "m4", "src": "良師 第65頁・精熟實力 25", "st": "良師", "pk": "ls", "pname": "良師講義（精選）", "pord": 999, "ctx": "", "fig": "", "q": "若 $x=\\dfrac{\\sqrt{6}+\\sqrt{5}}{\\sqrt{6}-\\sqrt{5}}$、$y=\\dfrac{\\sqrt{6}-\\sqrt{5}}{\\sqrt{6}+\\sqrt{5}}$，求 (1) $xy$　(2) $x+y$　(3) $x^2+y^2$。", "o": [], "a": 1, "e": "考點：雙項有理化＋乘法公式。\n先有理化：\n$x=\\dfrac{(\\sqrt{6}+\\sqrt{5})^2}{6-5}=11+2\\sqrt{30}$，$y=\\dfrac{(\\sqrt{6}-\\sqrt{5})^2}{6-5}=11-2\\sqrt{30}$\n(1) $x$ 和 $y$ 互為倒數 → $xy=1$\n(2) $x+y=(11+2\\sqrt{30})+(11-2\\sqrt{30})=22$\n(3) $x^2+y^2=(x+y)^2-2xy=22^2-2=482$\n★ $x^2+y^2=(x+y)^2-2xy$ 這個公式很好用，不用把 $x^2$ 硬算出來。", "h": [], "rep": true, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "(1) $1$　(2) $22$　(3) $482$"}, {"id": "mL-a15", "no": "a15", "c": "m5", "src": "良師 第65頁・會考模擬 19", "st": "良師", "pk": "ls", "pname": "良師講義（精選）", "pord": 999, "ctx": "", "fig": "", "q": "計算 $8\\sqrt{\\dfrac{1}{8}}+4\\sqrt{27}-2\\sqrt{8}+9\\sqrt{\\dfrac{1}{27}}$。", "o": [], "a": 1, "e": "考點：每一項先化最簡，再合併同類方根。\n$8\\sqrt{\\dfrac{1}{8}}=\\dfrac{8}{\\sqrt{8}}=\\sqrt{8}=2\\sqrt{2}$\n$4\\sqrt{27}=4\\times3\\sqrt{3}=12\\sqrt{3}$\n$2\\sqrt{8}=4\\sqrt{2}$\n$9\\sqrt{\\dfrac{1}{27}}=\\dfrac{9}{3\\sqrt{3}}=\\dfrac{3}{\\sqrt{3}}=\\sqrt{3}$\n原式 $=2\\sqrt{2}+12\\sqrt{3}-4\\sqrt{2}+\\sqrt{3}=-2\\sqrt{2}+13\\sqrt{3}$\n★ $\\dfrac{a}{\\sqrt{a}}=\\sqrt{a}$，例如 $\\dfrac{8}{\\sqrt{8}}=\\sqrt{8}$。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "$13\\sqrt{3}-2\\sqrt{2}$"}, {"id": "pA6-1", "no": "選擇 1", "c": "m5", "src": "翰林 A卷・第6回 選擇 1", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "下列根式的運算，正確的有哪些？\n(甲) $\\sqrt{2}+\\sqrt{10}=\\sqrt{12}$　(乙) $\\sqrt{13}-\\sqrt{8}=\\sqrt{5}$\n(丙) $\\sqrt{3}\\times\\sqrt{5}=\\sqrt{15}$　(丁) $\\sqrt{14}\\div\\sqrt{2}=\\sqrt{7}$", "o": ["甲乙", "甲丙", "乙丁", "丙丁"], "a": 3, "e": "考點：根號乘除可以合併，加減不能把根號內相加減。\n(甲)(乙) 加減不能直接合併 ✘\n(丙) $\\sqrt{3\\times5}=\\sqrt{15}$ ✔　(丁) $\\sqrt{14\\div2}=\\sqrt{7}$ ✔", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "pA6-2", "no": "選擇 2", "c": "m6", "src": "翰林 A卷・第6回 選擇 2", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "下列哪一個算式的值最大？", "o": ["$\\sqrt{\\frac{5}{3}}\\div\\sqrt{\\frac{25}{3}}\\times\\sqrt{\\frac{5}{2}}\\div\\sqrt{\\frac{9}{4}}$", "$\\sqrt{24}\\div\\sqrt{8}\\times\\sqrt{3}$", "$\\sqrt{(-4)^2}$", "$\\sqrt{13^2-12^2}$"], "a": 3, "e": "考點：逐一化簡再比較。\n(A) $\\sqrt{\\dfrac{5}{3}\\times\\dfrac{3}{25}\\times\\dfrac{5}{2}\\times\\dfrac{4}{9}}=\\sqrt{\\dfrac{2}{9}}=\\dfrac{\\sqrt{2}}{3}$\n(B) $\\sqrt{24\\div8\\times3}=\\sqrt{9}=3$\n(C) $\\sqrt{16}=4$\n(D) $\\sqrt{169-144}=\\sqrt{25}=5$ → 最大", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "pA6-3", "no": "選擇 3", "c": "m4", "src": "翰林 A卷・第6回 選擇 3", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "解方程式 $(\\sqrt{5}+1)x=4$，得 $x=$？", "o": ["$1$", "$2$", "$\\sqrt{5}-1$", "$\\frac{2}{3}(\\sqrt{5}+1)$"], "a": 2, "e": "考點：兩邊同除以 $\\sqrt{5}+1$，再有理化。\n$x=\\dfrac{4}{\\sqrt{5}+1}=\\dfrac{4(\\sqrt{5}-1)}{5-1}=\\sqrt{5}-1$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "pA6-4", "no": "選擇 4", "c": "m6", "src": "翰林 A卷・第6回 選擇 4", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "比較 $\\sqrt{2}+\\sqrt{3}$ 與 $\\sqrt{5}$ 的大小關係，何者較大？", "o": ["$\\sqrt{2}+\\sqrt{3}$", "$\\sqrt{5}$", "一樣大", "無法比較"], "a": 0, "e": "考點：平方比較。\n$(\\sqrt{2}+\\sqrt{3})^2=5+2\\sqrt{6}$，$(\\sqrt{5})^2=5$\n多了 $2\\sqrt{6}>0$ → $\\sqrt{2}+\\sqrt{3}$ 較大\n★ 這也說明 $\\sqrt{2}+\\sqrt{3}\\ne\\sqrt{5}$。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "pA6-5", "no": "選擇 5", "c": "m5", "src": "翰林 A卷・第6回 選擇 5", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "若 $\\sqrt{18}+\\sqrt{98}-\\sqrt{72}=\\sqrt{a}$，則 $a$ 之值為何？", "o": ["$16$", "$32$", "$48$", "$64$"], "a": 1, "e": "考點：化最簡、合併同類方根，再放回根號。\n$3\\sqrt{2}+7\\sqrt{2}-6\\sqrt{2}=4\\sqrt{2}=\\sqrt{16\\times2}=\\sqrt{32}$ → $a=32$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "pA6-6", "no": "選擇 6", "c": "m2", "src": "翰林 A卷・第6回 選擇 6", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "計算 $(1+\\sqrt{3}-\\sqrt{5})(1-\\sqrt{3}+\\sqrt{5})$ 之值為何？", "o": ["$5-2\\sqrt{3}$", "$7-4\\sqrt{15}$", "$-7+2\\sqrt{15}$", "$-10+3\\sqrt{5}$"], "a": 2, "e": "考點：分組後用平方差公式。\n$=[1+(\\sqrt{3}-\\sqrt{5})][1-(\\sqrt{3}-\\sqrt{5})]=1^2-(\\sqrt{3}-\\sqrt{5})^2$\n$(\\sqrt{3}-\\sqrt{5})^2=3-2\\sqrt{15}+5=8-2\\sqrt{15}$\n原式 $=1-8+2\\sqrt{15}=-7+2\\sqrt{15}$\n★ 把 $\\sqrt{3}-\\sqrt{5}$ 看成一整塊，就是 $(1+A)(1-A)$。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "pA6-7", "no": "選擇 7", "c": "m5", "src": "翰林 A卷・第6回 選擇 7", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "$-\\sqrt{12}$ 與下列何者不是同類方根？", "o": ["$\\sqrt{75}$", "$\\sqrt{27}$", "$-\\sqrt{24}$", "$-\\sqrt{48}$"], "a": 2, "e": "考點：化最簡後根號內相同才是同類方根。\n$-\\sqrt{12}=-2\\sqrt{3}$\n$\\sqrt{75}=5\\sqrt{3}$、$\\sqrt{27}=3\\sqrt{3}$、$-\\sqrt{48}=-4\\sqrt{3}$ → 同類\n$-\\sqrt{24}=-2\\sqrt{6}$ → 不是同類", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "pA6-8", "no": "選擇 8", "c": "m4", "src": "翰林 A卷・第6回 選擇 8", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "計算 $\\dfrac{9\\sqrt{3}+7\\sqrt{12}-5\\sqrt{48}}{(\\sqrt{5}+\\sqrt{2})(\\sqrt{2}-\\sqrt{5})}$ 之值為何？", "o": ["$\\sqrt{3}$", "$-\\sqrt{3}$", "$3$", "$-3$"], "a": 1, "e": "考點：分子合併同類方根，分母用平方差。\n分子：$9\\sqrt{3}+14\\sqrt{3}-20\\sqrt{3}=3\\sqrt{3}$\n分母：$(\\sqrt{2}+\\sqrt{5})(\\sqrt{2}-\\sqrt{5})=2-5=-3$\n原式 $=\\dfrac{3\\sqrt{3}}{-3}=-\\sqrt{3}$\n★ 注意分母是 $\\sqrt{2}-\\sqrt{5}$，平方差是 $2-5$，結果是負的。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "pA6-9", "no": "選擇 9", "c": "m3", "src": "翰林 A卷・第6回 選擇 9", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "小強用電腦設計正方形與長方形圖案，兩個圖案的面積均為 45 平方單位。請問正方形的邊長為何？", "o": ["$3\\sqrt{3}$", "$3\\sqrt{5}$", "$5\\sqrt{3}$", "$5\\sqrt{5}$"], "a": 1, "e": "考點：正方形邊長 $=\\sqrt{\\text{面積}}$。\n$\\sqrt{45}=\\sqrt{9\\times5}=3\\sqrt{5}$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "pA6-10", "no": "選擇 10", "c": "m2", "src": "翰林 A卷・第6回 選擇 10", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "承上題（兩個圖案面積均為 45 平方單位），若長方形的長為 $5\\sqrt{3}$，則長方形的寬為何？", "o": ["$3\\sqrt{3}$", "$3\\sqrt{5}$", "$5\\sqrt{3}$", "$5\\sqrt{5}$"], "a": 0, "e": "考點：寬 $=$ 面積 $\\div$ 長，再有理化。\n$\\dfrac{45}{5\\sqrt{3}}=\\dfrac{9}{\\sqrt{3}}=\\dfrac{9\\sqrt{3}}{3}=3\\sqrt{3}$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "pA6-11", "no": "填充 1", "c": "m5", "src": "翰林 A卷・第6回 填充 1", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "若 $\\sqrt{5}+\\sqrt{5}+\\sqrt{5}=\\sqrt{m}$，$\\sqrt{5}\\times\\sqrt{5}\\times\\sqrt{5}=\\sqrt{n}$，則 $m+n=$？", "o": [], "a": 1, "e": "考點：加法是係數相加；乘法是根號內相乘。\n$\\sqrt{5}+\\sqrt{5}+\\sqrt{5}=3\\sqrt{5}=\\sqrt{45}$ → $m=45$\n$\\sqrt{5\\times5\\times5}=\\sqrt{125}$ → $n=125$\n$m+n=170$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "$170$"}, {"id": "pA6-12", "no": "填充 2", "c": "m2", "src": "翰林 A卷・第6回 填充 2", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "計算 $(\\sqrt{7}+\\sqrt{8})^{2025}\\times(\\sqrt{8}-\\sqrt{7})^{2025}$。", "o": [], "a": 1, "e": "考點：指數相同可以先相乘：$a^n\\times b^n=(ab)^n$。\n$(\\sqrt{8}+\\sqrt{7})(\\sqrt{8}-\\sqrt{7})=8-7=1$\n原式 $=1^{2025}=1$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "$1$"}, {"id": "pA6-13", "no": "填充 3", "c": "m2", "src": "翰林 A卷・第6回 填充 3", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "利用平方差公式計算 $\\sqrt{43^2-18^2-25^2}$。", "o": [], "a": 1, "e": "考點：先用平方差把大數字變小。\n$43^2-18^2=(43+18)(43-18)=61\\times25$\n原式 $=\\sqrt{61\\times25-25^2}=\\sqrt{25\\times(61-25)}=\\sqrt{25\\times36}=5\\times6=30$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "$30$"}, {"id": "pA6-14", "no": "填充 4", "c": "m6", "src": "翰林 A卷・第6回 填充 4", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "介於 $\\dfrac{1}{2+\\sqrt{3}}$ 與 $\\dfrac{3}{2\\sqrt{7}-5}$ 之間的整數共有幾個？", "o": [], "a": 1, "e": "考點：先有理化，再估算。\n$\\dfrac{1}{2+\\sqrt{3}}=\\dfrac{2-\\sqrt{3}}{4-3}=2-\\sqrt{3}\\fallingdotseq0.27$\n$\\dfrac{3}{2\\sqrt{7}-5}=\\dfrac{3(2\\sqrt{7}+5)}{28-25}=2\\sqrt{7}+5\\fallingdotseq10.29$\n介於兩數之間的整數：1、2、…、10，共 10 個", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "$10$ 個"}, {"id": "pA6-15", "no": "填充 5", "c": "m6", "src": "翰林 A卷・第6回 填充 5", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "已知 $\\sqrt{37}\\fallingdotseq6.08$，$\\sqrt{370}\\fallingdotseq19.24$，利用根式的運算規則計算 $\\sqrt{0.037}\\fallingdotseq$？", "o": [], "a": 1, "e": "考點：根號內移兩位小數點，答案移一位。\n$\\sqrt{0.037}=\\sqrt{\\dfrac{370}{10000}}=\\dfrac{\\sqrt{370}}{100}\\fallingdotseq0.1924$\n★ 不是 $\\dfrac{\\sqrt{37}}{\\sqrt{1000}}$，1000 開不成整數，要選 370。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "$0.1924$"}, {"id": "pA6-16", "no": "計算 1", "c": "m6", "src": "翰林 A卷・第6回 計算 1", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "三位參加者分別從三個不同的點同時出發到達 $A$ 點：小歐走 $O\\to B\\to A$、熙熙走 $P\\to C\\to A$、阿迪走 $E\\to D\\to A$（$B$、$C$、$D$、$A$ 在同一直線上），其中 $\\overline{AB}=\\sqrt{7}$，$\\overline{AC}=\\sqrt{5}$，$\\overline{AD}=\\sqrt{3}$，$\\overline{OB}=\\sqrt{13}$，$\\overline{PC}=\\sqrt{15}$，$\\overline{ED}=\\sqrt{17}$。\n(1) 三人所走的路徑長分別為多少？\n(2) 如果三人的速率相同，則誰先到達 $A$ 點？", "o": [], "a": 1, "e": "考點：根式比大小用平方。\n(1) 小歐：$\\sqrt{13}+\\sqrt{7}$；熙熙：$\\sqrt{15}+\\sqrt{5}$；阿迪：$\\sqrt{17}+\\sqrt{3}$\n(2) 平方比較：\n$(\\sqrt{13}+\\sqrt{7})^2=20+2\\sqrt{91}$\n$(\\sqrt{15}+\\sqrt{5})^2=20+2\\sqrt{75}$\n$(\\sqrt{17}+\\sqrt{3})^2=20+2\\sqrt{51}$\n$\\sqrt{51}$ 最小 → 阿迪的路最短，阿迪先到\n★ 兩數和固定（都是 20）時，兩數越接近，乘積越大。", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "(1) 小歐 $\\sqrt{13}+\\sqrt{7}$、熙熙 $\\sqrt{15}+\\sqrt{5}$、阿迪 $\\sqrt{17}+\\sqrt{3}$　(2) 阿迪"}, {"id": "pA6-17", "no": "計算 2", "c": "m4", "src": "翰林 A卷・第6回 計算 2", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "計算下列各式，並將結果化為最簡根式：\n(1) $\\dfrac{1}{\\sqrt{2}+1}$\n(2) $\\dfrac{1}{\\sqrt{2}+1}+\\dfrac{1}{\\sqrt{3}+\\sqrt{2}}+\\dfrac{1}{\\sqrt{4}+\\sqrt{3}}+\\cdots+\\dfrac{1}{\\sqrt{49}+\\sqrt{48}}$", "o": [], "a": 1, "e": "考點：有理化後前後抵消。\n(1) $\\dfrac{\\sqrt{2}-1}{(\\sqrt{2}+1)(\\sqrt{2}-1)}=\\sqrt{2}-1$\n(2) 每項都是 $\\sqrt{n+1}-\\sqrt{n}$：\n$(\\sqrt{2}-1)+(\\sqrt{3}-\\sqrt{2})+\\cdots+(\\sqrt{49}-\\sqrt{48})=\\sqrt{49}-1=6$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "(1) $\\sqrt{2}-1$　(2) $6$"}, {"id": "pA6-18", "no": "計算 3", "c": "m3", "src": "翰林 A卷・第6回 計算 3", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "已知 $a$、$b$ 皆為正整數，且 $a$、$b$ 均不超過 100，若 $\\sqrt{48\\times a}$ 與 $\\sqrt{\\dfrac{72}{b}}$ 的值也都是正整數：\n(1) 求 $a$、$b$ 的最大值。\n(2) 承(1)，此時 $\\sqrt{48\\times a}$、$\\sqrt{\\dfrac{72}{b}}$ 的值分別為何？", "o": [], "a": 1, "e": "考點：根號內要是完全平方數。\n$48=2^4\\times3$，$72=2^3\\times3^2$\n(1) $48a$ 是完全平方數 → $a=3\\times k^2$，不超過 100 的最大是 $3\\times5^2=75$\n$\\dfrac{72}{b}$ 是完全平方數，$b$ 最大取 72（$\\dfrac{72}{72}=1=1^2$）\n(2) $\\sqrt{48\\times75}=\\sqrt{3600}=60$；$\\sqrt{\\dfrac{72}{72}}=1$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "(1) $a$ 最大 75，$b$ 最大 72　(2) $60$、$1$"}, {"id": "pA6-19", "no": "B填充 1", "c": "m4", "src": "翰林 A卷・第6回 B填充 1", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "計算下列各式，並將結果化為最簡根式：\n(1) $\\dfrac{2\\sqrt{3}-1}{2-\\sqrt{3}}-\\dfrac{2\\sqrt{3}+1}{2+\\sqrt{3}}-\\left(\\dfrac{4}{\\sqrt{6}+\\sqrt{2}}\\right)^2$\n(2) $\\dfrac{3+\\sqrt{6}}{5\\sqrt{3}-\\sqrt{32}+\\sqrt{50}-2\\sqrt{12}}$", "o": [], "a": 1, "e": "考點：有理化與化簡。\n(1) $\\dfrac{(2\\sqrt{3}-1)(2+\\sqrt{3})}{4-3}=4\\sqrt{3}+6-2-\\sqrt{3}=3\\sqrt{3}+4$\n$\\dfrac{(2\\sqrt{3}+1)(2-\\sqrt{3})}{4-3}=4\\sqrt{3}-6+2-\\sqrt{3}=3\\sqrt{3}-4$\n$\\dfrac{4}{\\sqrt{6}+\\sqrt{2}}=\\dfrac{4(\\sqrt{6}-\\sqrt{2})}{4}=\\sqrt{6}-\\sqrt{2}$，平方 $=8-2\\sqrt{12}=8-4\\sqrt{3}$\n原式 $=(3\\sqrt{3}+4)-(3\\sqrt{3}-4)-(8-4\\sqrt{3})=4\\sqrt{3}$\n(2) 分母 $=5\\sqrt{3}-4\\sqrt{2}+5\\sqrt{2}-4\\sqrt{3}=\\sqrt{3}+\\sqrt{2}$\n$\\dfrac{3+\\sqrt{6}}{\\sqrt{3}+\\sqrt{2}}$：分子 $3+\\sqrt{6}=\\sqrt{3}(\\sqrt{3}+\\sqrt{2})$ → 原式 $=\\sqrt{3}$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "(1) $4\\sqrt{3}$　(2) $\\sqrt{3}$"}, {"id": "pA6-20", "no": "B填充 2", "c": "m6", "src": "翰林 A卷・第6回 B填充 2", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "若 $\\sqrt{13}$ 的小數部分為 $a$，$\\dfrac{1}{a}$ 的小數部分為 $b$，則 $b=$？", "o": [], "a": 1, "e": "考點：小數部分＝原數－整數部分。\n$3<\\sqrt{13}<4$ → $a=\\sqrt{13}-3$\n$\\dfrac{1}{a}=\\dfrac{1}{\\sqrt{13}-3}=\\dfrac{\\sqrt{13}+3}{13-9}=\\dfrac{\\sqrt{13}+3}{4}\\fallingdotseq\\dfrac{6.6}{4}=1.65$\n整數部分是 1 → $b=\\dfrac{\\sqrt{13}+3}{4}-1=\\dfrac{\\sqrt{13}-1}{4}$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "$\\frac{\\sqrt{13}-1}{4}$"}, {"id": "pA6-21", "no": "B填充 3", "c": "m4", "src": "翰林 A卷・第6回 B填充 3", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "若 $x=2\\sqrt{5}-\\sqrt{3}$，$y=2\\sqrt{5}+\\sqrt{3}$，則 $\\dfrac{y}{x}+\\dfrac{x}{y}=$？", "o": [], "a": 1, "e": "考點：通分＋乘法公式。\n$\\dfrac{y}{x}+\\dfrac{x}{y}=\\dfrac{x^2+y^2}{xy}$\n$xy=20-3=17$\n$x^2+y^2=(23-4\\sqrt{15})+(23+4\\sqrt{15})=46$\n原式 $=\\dfrac{46}{17}$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "$\\frac{46}{17}$"}, {"id": "pA6-22", "no": "B填充 4", "c": "m3", "src": "翰林 A卷・第6回 B填充 4", "st": "考卷", "pk": "pA6", "pname": "翰林 A卷・第6回（2-2）", "pord": 106, "ctx": "", "fig": "", "q": "計算 $\\sqrt{359\\frac{1}{361}}$。", "o": [], "a": 1, "e": "考點：化假分數，找出完全平方。\n$359\\dfrac{1}{361}=\\dfrac{359\\times361+1}{361}$\n$359\\times361+1=(360-1)(360+1)+1=360^2$\n原式 $=\\dfrac{360}{19}$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "$\\frac{360}{19}$"}, {"id": "pA10-2", "no": "選擇 2", "c": "m6", "src": "翰林 A卷・第10回 選擇 2", "st": "考卷", "pk": "pA10", "pname": "翰林 A卷・第10回（2-2～3-2 複習）", "pord": 110, "ctx": "", "fig": "", "q": "數線上 $A$、$B$、$C$、$D$、$E$ 的坐標依序為 4、5、6、7、8，則 $10-2\\sqrt{5}$ 在數線上的位置應在哪兩點之間？", "o": ["$A$ 點和 $B$ 點", "$B$ 點和 $C$ 點", "$C$ 點和 $D$ 點", "$D$ 點和 $E$ 點"], "a": 1, "e": "考點：估算根式。\n$2\\sqrt{5}=\\sqrt{20}$，$4<\\sqrt{20}<5$（約 4.47）\n$10-4.47\\fallingdotseq5.53$ → 在 5 和 6 之間（$B$、$C$）", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "pA10-3", "no": "選擇 3", "c": "m5", "src": "翰林 A卷・第10回 選擇 3", "st": "考卷", "pk": "pA10", "pname": "翰林 A卷・第10回（2-2～3-2 複習）", "pord": 110, "ctx": "", "fig": "", "q": "計算 $\\sqrt{8}-\\sqrt{50}+6\\sqrt{5}+3\\sqrt{2}-\\sqrt{125}$ 之值為何？", "o": ["$0$", "$\\sqrt{2}$", "$\\sqrt{5}$", "$5\\sqrt{2}-\\sqrt{5}$"], "a": 2, "e": "考點：化最簡、合併同類方根。\n$2\\sqrt{2}-5\\sqrt{2}+6\\sqrt{5}+3\\sqrt{2}-5\\sqrt{5}=0\\cdot\\sqrt{2}+\\sqrt{5}=\\sqrt{5}$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "pA10-4", "no": "選擇 4", "c": "m2", "src": "翰林 A卷・第10回 選擇 4", "st": "考卷", "pk": "pA10", "pname": "翰林 A卷・第10回（2-2～3-2 複習）", "pord": 110, "ctx": "", "fig": "", "q": "若 $a=\\sqrt{3}-\\sqrt{2}$，則 $-(a+2)(a-2)$ 之值為何？", "o": ["$-9+2\\sqrt{6}$", "$-1+2\\sqrt{6}$", "$1-2\\sqrt{6}$", "$-1$"], "a": 1, "e": "考點：先用平方差化簡，再代入。\n$-(a+2)(a-2)=-(a^2-4)=4-a^2$\n$a^2=(\\sqrt{3}-\\sqrt{2})^2=5-2\\sqrt{6}$\n原式 $=4-5+2\\sqrt{6}=-1+2\\sqrt{6}$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": false, "ans": ""}, {"id": "pA10-12", "no": "填充 2", "c": "m2", "src": "翰林 A卷・第10回 填充 2", "st": "考卷", "pk": "pA10", "pname": "翰林 A卷・第10回（2-2～3-2 複習）", "pord": 110, "ctx": "", "fig": "", "q": "計算 $\\sqrt{\\dfrac{887^2+387^2}{2}-887\\times387}$。", "o": [], "a": 1, "e": "考點：湊成完全平方。\n$\\dfrac{887^2+387^2}{2}-887\\times387=\\dfrac{887^2-2\\times887\\times387+387^2}{2}=\\dfrac{(887-387)^2}{2}=\\dfrac{500^2}{2}$\n開根號：$\\dfrac{500}{\\sqrt{2}}=250\\sqrt{2}$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "$250\\sqrt{2}$"}, {"id": "pA10-13", "no": "填充 3", "c": "m2", "src": "翰林 A卷・第10回 填充 3", "st": "考卷", "pk": "pA10", "pname": "翰林 A卷・第10回（2-2～3-2 複習）", "pord": 110, "ctx": "", "fig": "", "q": "若 $x=\\sqrt{7}+\\sqrt{6}$，$y=\\sqrt{6}-\\sqrt{7}$，則 $2x^2+4xy+2y^2=$？", "o": [], "a": 1, "e": "考點：先因式分解再代入。\n$2x^2+4xy+2y^2=2(x+y)^2$\n$x+y=2\\sqrt{6}$ → $2\\times24=48$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "$48$"}, {"id": "pA10-16", "no": "計算 1", "c": "m6", "src": "翰林 A卷・第10回 計算 1", "st": "考卷", "pk": "pA10", "pname": "翰林 A卷・第10回（2-2～3-2 複習）", "pord": 110, "ctx": "", "fig": "", "q": "比較下列各組數的大小關係：\n(1) $x=-\\sqrt{2}-\\sqrt{6}$，$y=-\\sqrt{3}-\\sqrt{5}$，$z=-\\sqrt{4}-\\sqrt{4}$\n(2) $a=\\sqrt{8}-\\sqrt{4}$，$b=\\sqrt{6}-\\sqrt{2}$，$c=\\sqrt{7}-\\sqrt{3}$", "o": [], "a": 1, "e": "考點：負數比絕對值（反過來）；兩數差用倒數有理化。\n(1) 平方：$x^2=8+2\\sqrt{12}$、$y^2=8+2\\sqrt{15}$、$z^2=8+2\\sqrt{16}$ → $|z|>|y|>|x|$\n都是負數，絕對值越大越小 → $x>y>z$\n(2) $\\dfrac{1}{a}=\\dfrac{\\sqrt{8}+\\sqrt{4}}{4}$、$\\dfrac{1}{b}=\\dfrac{\\sqrt{6}+\\sqrt{2}}{4}$、$\\dfrac{1}{c}=\\dfrac{\\sqrt{7}+\\sqrt{3}}{4}$\n由 (1) 的方法：$\\sqrt{8}+\\sqrt{4}>\\sqrt{7}+\\sqrt{3}>\\sqrt{6}+\\sqrt{2}$ → $\\dfrac{1}{a}>\\dfrac{1}{c}>\\dfrac{1}{b}$\n都是正數，倒數越大原數越小 → $b>c>a$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "(1) $x>y>z$　(2) $b>c>a$"}, {"id": "pA10-19", "no": "B填充 1", "c": "m2", "src": "翰林 A卷・第10回 B填充 1", "st": "考卷", "pk": "pA10", "pname": "翰林 A卷・第10回（2-2～3-2 複習）", "pord": 110, "ctx": "", "fig": "", "q": "若 $a+b=3\\sqrt{5}+2\\sqrt{3}$，且 $a-b=3\\sqrt{5}-2\\sqrt{3}$，則 $9a^2-9b^2=$？", "o": [], "a": 1, "e": "考點：$a^2-b^2=(a+b)(a-b)$。\n$9(a+b)(a-b)=9[(3\\sqrt{5})^2-(2\\sqrt{3})^2]=9\\times(45-12)=297$", "h": [], "rep": false, "img": "", "imgnote": "", "fh": "", "maps": [], "chk": "", "orig": "", "fill": true, "ans": "$297$"}], "extras": [{"id": "formula", "title": "公式卡", "html": "<h3>乘除法則</h3><div class=\"fbox\"><div class=\"fl\">$\\sqrt{a}\\times\\sqrt{b}=\\sqrt{ab}$　（$a,b\\ge0$）</div><div class=\"fl\">$\\sqrt{a}\\div\\sqrt{b}=\\sqrt{\\frac{a}{b}}$　（$a\\ge0,\\ b>0$）</div><div class=\"fl\">$a\\times b\\sqrt{n}=ab\\sqrt{n}$</div><div class=\"fl\">$\\sqrt{a^2b}=a\\sqrt{b}$　（$a\\ge0$）</div></div><h3>最簡根式三不準</h3><div class=\"fbox\"><div class=\"fl\">根號內不留平方因數：$\\sqrt{12}\\to2\\sqrt{3}$</div><div class=\"fl\">根號內不留分數或小數：$\\sqrt{\\frac{1}{3}}\\to\\frac{\\sqrt{3}}{3}$</div><div class=\"fl\">分母不留根號：$\\frac{1}{\\sqrt{2}}\\to\\frac{\\sqrt{2}}{2}$</div></div><h3>有理化分母</h3><div class=\"fbox\"><div class=\"fl\">單項：$\\frac{b}{\\sqrt{a}}=\\frac{b\\sqrt{a}}{a}$</div><div class=\"fl\">雙項：$\\frac{c}{\\sqrt{a}+\\sqrt{b}}=\\frac{c(\\sqrt{a}-\\sqrt{b})}{a-b}$</div><div class=\"fl\">平方差：$(x+y)(x-y)=x^2-y^2$</div></div><h3>乘法公式</h3><div class=\"fbox\"><div class=\"fl\">$(a+b)^2=a^2+2ab+b^2$</div><div class=\"fl\">$(a-b)^2=a^2-2ab+b^2$</div><div class=\"fl\">$(\\sqrt{a}+\\sqrt{b})(\\sqrt{a}-\\sqrt{b})=a-b$</div></div><h3>同類方根</h3><div class=\"fbox\"><div class=\"fl\">化最簡後根號內相同才能合併：$6\\sqrt{3}-4\\sqrt{3}=2\\sqrt{3}$</div><div class=\"fl\">$\\sqrt{2}+\\sqrt{3}\\ne\\sqrt{5}$</div></div><h3>估算與比大小</h3><div class=\"fbox\"><div class=\"fl\">$a>b>0 \\iff \\sqrt{a}>\\sqrt{b}$</div><div class=\"fl\">係數放回根號內再比：$8\\sqrt{5}=\\sqrt{320}$</div><div class=\"fl\">常用：$\\sqrt{2}\\fallingdotseq1.414$、$\\sqrt{3}\\fallingdotseq1.732$、$\\sqrt{5}\\fallingdotseq2.236$、$\\sqrt{7}\\fallingdotseq2.646$</div></div>"}, {"id": "flow", "title": "運算步驟", "html": "<h3>根式四則運算四步驟</h3><div class=\"fbox\"><div class=\"fl\">① 化最簡根式（質因數分解，提出平方數）</div><div class=\"fl\">② 先乘除，用分配律、乘法公式展開</div><div class=\"fl\">③ 分母有理化（單項乘根號；雙項乘共軛式）</div><div class=\"fl\">④ 合併同類方根</div></div>"}, {"id": "compare", "title": "易混淆比較", "html": "<h3>易混淆比較</h3><div class=\"tbl\"><table><thead><tr><th>比較項目</th><th>觀念 A</th><th>觀念 B</th><th>核心差異與常見陷阱</th></tr></thead><tbody><tr><td>根式乘法 vs 根式加減</td><td>\\(\\sqrt{a} \\times \\sqrt{b} = \\sqrt{ab}\\)</td><td>\\(\\sqrt{a} + \\sqrt{b} \\ne \\sqrt{a+b}\\)</td><td>乘法可直接合併被開方數；加減法絕對不能直接將根號內數字相加，只有同類方根才能合併係數。</td></tr><tr><td>最簡根式判定</td><td>\\(\\sqrt{12} = 2\\sqrt{3}\\)（最簡）</td><td>\\(\\sqrt{12}\\) 或 \\(\\frac{1}{\\sqrt{3}}\\)（非最簡）</td><td>根號內含完全平方因數（如 \\(12 = 2^2 \\times 3\\)）或分母帶有根號時，皆非最簡根式，必須化簡並有理化。</td></tr><tr><td>單項有理化 vs 雙項有理化</td><td>分母為 \\(\\sqrt{a}\\) 型</td><td>分母為 \\(\\sqrt{a} \\pm \\sqrt{b}\\) 型</td><td>單項只需同乘 \\(\\sqrt{a}\\)；雙項必須同乘共軛式利用平方差公式 \\((a+b)(a-b)=a^2-b^2\\) 去除根號。</td></tr></tbody></table></div>"}, {"id": "tips", "title": "常見錯誤", "html": "<h3>常見錯誤</h3><div class=\"fbox\"><div class=\"fl\">$\\sqrt{2}+\\sqrt{3}=\\sqrt{5}$ ✘（不能把根號內相加）</div><div class=\"fl\">$4\\sqrt{3}\\times2\\sqrt{3}=8\\sqrt{3}$ ✘（應為 $8\\times3=24$）</div><div class=\"fl\">$\\sqrt{2}\\times\\sqrt{5}=2\\sqrt{5}$ ✘（應為 $\\sqrt{10}$）</div><div class=\"fl\">減號後面的括號打開要變號</div><div class=\"fl\">答案一定要化成最簡根式</div></div>"}], "focus": ["m2-11", "mL-a1", "m2-19", "m2-3", "m2-21", "m2-6", "m2-8", "mL-a7", "m2-18", "mL-a8", "m2-14", "mL-a10", "mL-a9", "mL-a13", "mL-a14"]});
